  [animation]
  (when animation
    (obj/without-empty
     (case (:animation-type animation)

       :dissolve
       #js {:type "dissolve"
            :duration (:duration animation)
            :easing (format-key (:easing animation))}

       :slide
       #js {:type "slide"
            :way (format-key (:way animation))
            :direction (format-key (:direction animation))
